/* One Help & Shortcuts window, with offline English and Marathi tutorial PDFs. */
(()=>{'use strict';const $=id=>document.getElementById(id),urls=new Map();let selectedLanguage;
function appLanguage(){return window.KPPreferences?.get().language==='marathi'?'marathi':'english';}
function guideLanguage(){return selectedLanguage||appLanguage();}
function guideData(lang=guideLanguage()){const packet=JSON.parse($('kp-user-tutorial-pdf').textContent);return packet.translations?.[lang]||packet;}
function pdfURL(lang=guideLanguage()){if(!urls.has(lang)){const data=guideData(lang),raw=atob(data.base64);urls.set(lang,URL.createObjectURL(new Blob([Uint8Array.from(raw,c=>c.charCodeAt(0))],{type:'application/pdf'})));}return urls.get(lang);}
function updateGuide(){const mr=guideLanguage()==='marathi',box=$('help-tutorial-content');for(const n of box.querySelectorAll('[data-guide-en]'))n.textContent=mr?n.dataset.guideMr:n.dataset.guideEn;$('help-guide-language').value=guideLanguage();for(const id of ['help-open-pdf','help-download-pdf'])$(id).href=pdfURL();$('help-download-pdf').download=guideData().file;const viewer=$('help-tutorial-viewer');viewer.title=mr?'KP MASTER सॉफ्टवेअर वापर मार्गदर्शक PDF':'KP MASTER software tutorial PDF';if(!viewer.hidden)viewer.src=pdfURL()+'#toolbar=1&view=FitH';}
function language(){const mr=appLanguage()==='marathi';for(const n of document.querySelectorAll('[data-help-en]'))n.textContent=mr?n.dataset.helpMr:n.dataset.helpEn;$('help-close').setAttribute('aria-label',mr?'मदत बंद करा':'Close help');updateGuide();}
function bind(node,en,mr){if(!node)return;node.dataset.helpEn=en;node.dataset.helpMr=mr;}
function init(){const box=$('help-tutorial-content'),dialog=$('workspace-help');dialog.dataset.noLocalize='true';box.dataset.noLocalize='true';box.innerHTML='<h2 data-guide-en="KP MASTER 1.2.11 — Software tutorial" data-guide-mr="KP MASTER 1.2.11 — सॉफ्टवेअर वापर मार्गदर्शक"></h2><p data-guide-en="A4 tutorial PDFs in English and Marathi. Charts, predictions, Ruling Planets, transit searches, settings, printing and backups. Available offline." data-guide-mr="इंग्रजी व मराठीतील A4 PDF मार्गदर्शक. कुंडली, भविष्य, शासक ग्रह, गोचर शोध, सेटिंग, छपाई व बॅकअप यांची माहिती. इंटरनेटशिवाय उपलब्ध."></p><label class="help-guide-language"><span data-guide-en="Tutorial language" data-guide-mr="मार्गदर्शकाची भाषा"></span><select id="help-guide-language" aria-label="Tutorial language"><option value="english">English</option><option value="marathi">मराठी</option></select></label><div class="help-pdf-actions"><button type="button" id="help-view-pdf" data-guide-en="View tutorial PDF" data-guide-mr="मार्गदर्शक PDF पहा"></button><a id="help-open-pdf" target="_blank" rel="noopener" data-guide-en="Open PDF in new tab" data-guide-mr="PDF नव्या टॅबमध्ये उघडा"></a><a id="help-download-pdf" data-guide-en="Download PDF" data-guide-mr="PDF डाउनलोड करा"></a></div><p data-guide-en="If the embedded PDF viewer is unavailable, use Open PDF or Download PDF." data-guide-mr="PDF येथे दिसत नसल्यास नव्या टॅबमध्ये उघडा किंवा डाउनलोड करा."></p><iframe id="help-tutorial-viewer" title="KP MASTER software tutorial PDF" hidden></iframe>';
 dialog.append(box);document.querySelector('.app-sidebar nav [data-tab="help"]')?.remove();const open=$('help-open');open.innerHTML='<svg><use href="#i-help"/></svg><span data-help-en="Help & shortcuts" data-help-mr="मदत व शॉर्टकट"></span><kbd>?</kbd>';
 bind(dialog.querySelector('.eyebrow'),'HELP & SHORTCUTS','मदत व शॉर्टकट');bind(dialog.querySelector('.help-heading h2'),'Help & shortcuts','मदत व शॉर्टकट');bind(dialog.querySelector(':scope>p'),'Begin with birth details, enter your manual Raphael and ephemeris values, then review the kundali and print report. All Marathi calculation worksheets remain available in the navigation.','जन्मतपशील भरा, आवश्यक राफेल व ग्रहस्थितीची मूल्ये नोंदवा आणि कुंडली व अहवाल तपासा. मराठी गणना पत्रके नेव्हिगेशनमध्ये उपलब्ध आहेत.');bind(dialog.querySelector('.help-tip'),'Keep your work safe. Save the current chart and export a chart file for a portable backup or to move it to another device.','नोंदी सुरक्षित ठेवा. सध्याची कुंडली जतन करा आणि बॅकअपसाठी किंवा दुसऱ्या उपकरणावर नेण्यासाठी स्वतंत्र कुंडली फाइल निर्यात करा.');bind(dialog.querySelector(':scope>h3'),'Keyboard shortcuts','कीबोर्ड शॉर्टकट');const terms=[['Save chart','कुंडली जतन करा'],['Calculate chart','कुंडलीची गणना करा'],['Open this guide','मदत उघडा'],['Close navigation or guide','नेव्हिगेशन किंवा मदत बंद करा']];dialog.querySelectorAll('dt').forEach((n,i)=>{if(terms[i])bind(n,...terms[i]);});
 $('help-guide-language').addEventListener('change',()=>{selectedLanguage=$('help-guide-language').value;updateGuide();});$('help-view-pdf').onclick=()=>{const viewer=$('help-tutorial-viewer');viewer.src=pdfURL()+'#toolbar=1&view=FitH';viewer.hidden=false;};language();window.addEventListener('kp-preferences-changed',()=>{selectedLanguage=null;language();});}
window.KPUserTutorial=Object.freeze({pdfURL,guideLanguage});if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();})();
